<?php $storeIndex = $storesById ?? array_column(app('storeRepository')->all(), null, 'id'); ?>
<div class="coupon-grid"><?php foreach ($offers as $offer): ?><?php $store = $storeIndex[(int) $offer['store_id']] ?? null; ?><article class="coupon"><div class="coupon-top"><div class="coupon-store"><div class="mini-logo"><?php echo e($store['initial'] ?? '?'); ?></div><?php echo e($store['name'] ?? 'Store'); ?></div><span class="tag <?php echo $offer['type'] === 'CODICE' ? 'tag-code' : 'tag-offer'; ?>"><?php echo e($offer['type']); ?></span></div><h3><a href="<?php echo e(url('/coupon/' . $offer['slug'])); ?>"><?php echo e($offer['title']); ?></a></h3><p class="coupon-desc"><?php echo e($offer['description']); ?></p><div class="coupon-bottom"><div class="coupon-discount"><?php echo e($offer['discount']); ?></div><?php if (! empty($offer['code'])): ?><button class="redeem" type="button" data-offer-code="<?php echo e($offer['code']); ?>">Mostra codice</button><?php else: ?><a class="redeem" href="<?php echo e(url('/go/' . $offer['id'])); ?>" rel="nofollow sponsored noopener">Vai all'offerta</a><?php endif; ?></div><div class="expiry">◷ Scade il <?php echo e($offer['expires_at']); ?></div></article><?php endforeach; ?></div>
